<span class="line"><span style="color:#C678DD;">def</span><span style="color:#61AFEF;"> _get_nsp_data_from_paragraph</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;font-style:italic;">paragraph</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;font-style:italic;">paragraphs</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;font-style:italic;">vocab</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;font-style:italic;">max_len</span><span style="color:#ABB2BF;">):</span></span>
